/// Starts a scan of every channel and answers when it ends (about 2 s), with the access points heard. While joining
/// or joined it does not leave the channel and answers the list as it stands.
pub fn scan(endpoint: Endpoint) -> Result<core::result::Result<List<Network, 32>, Error>> {
    let mut buffer = Pages::new(4096).ok_or(SysError::NoMemory)?;
    let length = {
        let mut w = Writer::new(buffer.as_mut_slice());
        w.len()
    };
    let reply = wire::call_buffer(endpoint, 1 | MAJOR << 8, &buffer, length)?;
    if let Some(code) = wire::enum_error(&reply)? { return Ok(Err(Error::from_code(code).ok_or(SysError::Invalid)?)); }
    let length = wire::buffer_reply(&reply, 1474, false, false)?;
    let length = length.ok_or(SysError::Invalid)?;
    Ok(Ok({ let mut r = Reader::new(&buffer.as_slice()[..length]); <List<Network, 32> as Wire>::decode(&mut r).filter(|_| r.done()).ok_or(SysError::Invalid)? }))
}

/// Starts joining the strongest access point of `ssid` from the last scan (`status` follows). `passphrase` empty for
/// an open network or one the station remembers. `remember` has `keystore` keep the network's key (550-NET-0024): it
/// alone holds it, and the station gets each handshake's keys from it (MC-11.9); `unsupported` when it cannot. The
/// passphrase is never answered back. Change badge only.
pub fn join(endpoint: Endpoint, ssid: &[u8], passphrase: &str, remember: bool) -> Result<core::result::Result<(), Error>> {
    let mut buffer = Pages::new(4096).ok_or(SysError::NoMemory)?;
    let length = {
        let mut w = Writer::new(buffer.as_mut_slice());
        codec::encode_slice::<u8, 32>(ssid, &mut w).ok_or(SysError::Invalid)?;
        codec::encode_str::<64>(passphrase, &mut w).ok_or(SysError::Invalid)?;
        remember.encode(&mut w).ok_or(SysError::Invalid)?;
        w.len()
    };
    let reply = wire::call_buffer(endpoint, 2 | MAJOR << 8, &buffer, length)?;
    if let Some(code) = wire::enum_error(&reply)? { return Ok(Err(Error::from_code(code).ok_or(SysError::Invalid)?)); }
    let length = wire::buffer_reply(&reply, 0, false, false)?;
    if length != Some(0) { return Err(SysError::Invalid); }
    Ok(Ok(()))
}

